def get_user_input():
    """Get user input for the operation and numbers."""
    while True:
        operation = input("Choose the operation (add, subtract, multiply, divide): ").lower()
        if operation in ['add', 'subtract', 'multiply', 'divide']:
            break
        else:
            print("Invalid input. Please choose one of the four operations.")

    num1 = float(input("Enter the first number: "))
    num2 = float(input("Enter the second number: "))

    return operation, num1, num2

def perform_operation(operation, num1, num2):
    """Perform the chosen operation and return the result."""
    if operation == 'add':
        result = num1 + num2
    elif operation == 'subtract':
        result = num1 - num2
    elif operation == 'multiply':
        result = num1 * num2
    elif operation == 'divide':
        if num2 == 0:
            print("Error: Division by zero is not allowed.")
            return None
        result = num1 / num2
    else:
        print("Invalid operation. Please choose one of the four operations.")
        return None

    return result

def main():
    operation, num1, num2 = get_user_input()
    result = perform_operation(operation, num1, num2)

    if result is not None:
        print(f"{num1} {operation} {num2} = {result}")

if __name__ == "__main__":
    main()
```

This program defines three functions: `get_user_input()` to get user input for the operation and numbers, `perform_operation()` to perform the chosen operation and return the result, and `main()` to call the other two functions and display the result. The program checks for invalid user input and division by zero before performing the operation.
